using System.Globalization;
using TLCPlus;
namespace TLCPlus.Desktop;
public partial class MainForm:Form
{
    public Project Project {get;private set;}=new();
    public TedDocument? Ted {get;private set;}
    public Course? Preview {get;private set;}
    public readonly TrackCanvas Canvas=new(){Dock=DockStyle.Fill};
    readonly ElevationView elevation=new(){Dock=DockStyle.Fill};
    readonly ToolStripStatusLabel status=new(){Spring=true,TextAlign=ContentAlignment.MiddleLeft};
    readonly ToolStripStatusLabel coords=new(){Text=""};
    readonly Label summary=new(){Dock=DockStyle.Top,Height=77,Padding=new(18,12,10,8)};
    readonly ToolStrip tools=new(){GripStyle=ToolStripGripStyle.Hidden,Padding=new(12,5,5,5),ImageScalingSize=new(20,20)};
    readonly List<State> undo=[],redo=[];State stable=null!;bool binding,dirty,gesture;string? file;string? previewError;
    record State(Project Project,byte[]? Ted);
    static Color Bg=Color.FromArgb(30,30,30),TextColor=Color.FromArgb(224,224,224),Accent=Color.FromArgb(100,210,255);
    public MainForm(string? path=null) { BuildPythonInterface(path); }
    static DataGridView Grid()=>new(){Dock=DockStyle.Fill,BackgroundColor=Bg,ForeColor=Color.Black,AutoGenerateColumns=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells,BorderStyle=BorderStyle.None,EditMode=DataGridViewEditMode.EditOnKeystrokeOrF2};
    static void Style(PropertyGrid p){p.ViewBackColor=Bg;p.ViewForeColor=TextColor;p.HelpBackColor=Bg;p.HelpForeColor=TextColor;p.CategoryForeColor=Accent;p.LineColor=Color.FromArgb(45,54,70);p.CommandsBackColor=Bg;}
    static ToolStripMenuItem AddMenu(MenuStrip menu,string name){var m=new ToolStripMenuItem(name);menu.Items.Add(m);return m;}
    static void Item(ToolStripMenuItem menu,string label,Action action,Keys keys=Keys.None){var item=new ToolStripMenuItem(label){ShortcutKeys=keys};item.Click+=(_,_)=>Try(action);menu.DropDownItems.Add(item);}
    static void Check(ToolStripMenuItem menu,string label,bool value,Action<bool> action){var i=new ToolStripMenuItem(label){CheckOnClick=true,Checked=value};i.CheckedChanged+=(_,_)=>Try(()=>action(i.Checked));menu.DropDownItems.Add(i);}
    static Button Button(Control parent,string label,Action action){var b=new Button{Text=label,AutoSize=true,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(39,50,67),ForeColor=TextColor,Margin=new(3,5,3,5),Padding=new(7,4,7,4)};b.FlatAppearance.BorderColor=Color.FromArgb(65,82,105);b.Click+=(_,_)=>Try(action);parent.Controls.Add(b);return b;}
    void Tool(string label,Action action){var b=new ToolStripButton(label);b.Click+=(_,_)=>Try(action);tools.Items.Add(b);}
    static void Try(Action action){if(Program.SmokeMode){action();return;}try{action();}catch(Exception e){MessageBox.Show(e.Message,"TLC+",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    State Snapshot()=>new(Project.Copy(),Ted?.Write());
    void Restore(State s){Project=s.Project.Copy();Ted=s.Ted==null?null:TedDocument.Read(s.Ted);Canvas.Selected.Clear();stable=Snapshot();dirty=true;Bind();}
    public void Commit(){if(binding||gesture)return;undo.Add(stable);if(undo.Count>200)undo.RemoveAt(0);redo.Clear();stable=Snapshot();dirty=true;Bind();}
    public void Undo(){if(undo.Count==0)return;redo.Add(Snapshot());var s=undo[^1];undo.RemoveAt(undo.Count-1);Restore(s);}
    public void Redo(){if(redo.Count==0)return;undo.Add(Snapshot());var s=redo[^1];redo.RemoveAt(redo.Count-1);Restore(s);}
    public void Bind(){Canvas.Project=Project;if(Ted!=null&&Canvas.Tool is not ("road" or "road-erase"))Canvas.Tool="pan";RefreshPythonControls();UpdatePreview();Selection();RefreshWindowTitle();}
    void RefreshWindowTitle()=>Text=$"{(dirty?"* ":"")}{(file==null?UiLanguage.T("Untitled"):Path.GetFileName(file))} — TLC+ C# 1.0.2 (Python 1.3.0 port)";
    public void UpdatePreview(){if(gesture&&Canvas.DraftMode&&Canvas.IsInteracting){ScheduleInteractivePreview();return;}EndInteractivePreview();FullPreviewBuilds++;previewError=null;try{Preview=Ted?.Course??(Project.Nodes.Count>=(Project.Settings.Circuit?3:2)?Exporter.Build(Project):null);}catch(Exception e){Preview=null;previewError=e.Message;}Canvas.Course=Preview??BaseRoadPreview(false);elevation.Course=Canvas.Course;elevation.Project=Project;RefreshPythonControls();if(previewError!=null&&Project.RoadPlacements.Count>0){roadTypeHint.Text+="\n"+previewError+"\nUndo the geometry change or clear road types before exporting.";}Canvas.Invalidate();elevation.Invalidate();string mode=Ted==null?(Project.Settings.Circuit?"CIRCUIT":"POINT TO POINT"):"TED • PRESERVE BYTES";summary.Text=$"{mode}\n{(Preview==null?"Place nodes to begin":$"{Preview.Length:N1} m  ·  {Preview.Corners} corners  ·  {Preview.Heights.Count:N0} height samples")}";summary.ForeColor=Accent;status.Text=previewError??$"{Project.Nodes.Count} nodes  ·  {Canvas.Selected.Count} selected  ·  {Canvas.Tool}  ·  Ctrl-drag snaps to {Canvas.GridSize:0} m";}
    void Selection(bool syncGrid=true){Canvas.Selected.RemoveWhere(i=>i<0||i>=Project.Nodes.Count);Canvas.Invalidate();}
    void SetTool(string tool){if(Ted!=null&&tool=="pen"){status.Text="Import this TED as an editable path to change its layout.";return;}Canvas.Tool=tool;Canvas.Cursor=tool is "pen" or "road" or "road-erase"?Cursors.Cross:tool=="pan"?Cursors.Hand:Cursors.Default;status.Text=$"{tool} tool selected";}
    bool ConfirmDiscard(){if(!dirty)return true;var r=MessageBox.Show("Save your changes before continuing?","TLC+",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(r==DialogResult.Cancel)return false;if(r==DialogResult.Yes){Save(false);return !dirty;}return true;}
    public void NewProject(){if(!ConfirmDiscard())return;Project=new();Ted=null;file=null;Reset();}
    void Reset(){dirty=false;undo.Clear();redo.Clear();stable=Snapshot();Canvas.Selected.Clear();Bind();Canvas.Fit();}
    void OpenDialog(){using var d=new OpenFileDialog{Filter="TLC tracks|*.trk*;*.ted|All files|*.*"};if(d.ShowDialog()==DialogResult.OK&&ConfirmDiscard())OpenFile(d.FileName);}
    public void OpenFile(string path){string ext=Path.GetExtension(path).ToLowerInvariant();if(ext==".ted"){Ted=TedDocument.Read(File.ReadAllBytes(path));Project=new(){Settings=Ted.Settings};}else{Project=ext==".json"?Project.Load(path):DocumentFiles.LoadLayout(path);Ted=null;}file=path;Reset();}
    string? ChooseSave(string filter,string ext,string? suggested=null){using var d=new SaveFileDialog{Filter=filter,DefaultExt=ext,AddExtension=true,FileName=suggested??(file==null?"Untitled":Path.GetFileNameWithoutExtension(file)),OverwritePrompt=true};return d.ShowDialog()==DialogResult.OK?d.FileName:null;}
    void Flush(){Validate();}
    public void Save(bool saveAs){Flush();string? path=file;if(Ted==null&&path!=null&&!path.EndsWith(".trk5",StringComparison.OrdinalIgnoreCase))path=null;if(path==null||saveAs)path=ChooseSave(Ted!=null?"GT6 TED|*.ted":"TLC+ layout|*.trk5",Ted!=null?"ted":"trk5");if(path==null)return;if(Ted!=null)File.WriteAllBytes(path,Ted.Write());else DocumentFiles.SaveLayout(path,Project);file=path;dirty=false;stable=Snapshot();Bind();}
    void SaveTrk(){if(Ted!=null)throw new InvalidOperationException("Import the TED path as a layout first, or save its TED tables directly.");Flush();string? p=ChooseSave("TLC+ layout|*.trk5","trk5");if(p!=null){DocumentFiles.SaveLayout(p,Project);file=p;dirty=false;stable=Snapshot();Bind();}}
    void ExportTed(){Flush();if(Ted==null&&Preview==null)throw new InvalidOperationException(previewError??"Place more nodes to export a track.");string? p=ChooseSave("GT6 TED|*.ted","ted");if(p!=null){File.WriteAllBytes(p,Ted?.Write()??Exporter.Write(Project));status.Text="TED exported: "+p;}}
    void ExportCsv(){string? p=ChooseSave("CSV path|*.csv","csv");if(p!=null)Importers.WriteCsv(p,Project.Nodes);}
    void ExportImage(){string? p=ChooseSave("PNG preview|*.png","png");if(p!=null){using var b=Canvas.Render();b.Save(p);}}
    void ExportSvg(){if(Preview==null)return;string? p=ChooseSave("SVG vector preview|*.svg","svg");if(p==null)return;var pts=new List<Vec>();for(double d=0;d<Preview.PlanLength;d+=4)pts.Add(Geometry.At(Preview.Points,d).Point);if(pts.Count==0)return;double x=pts.Min(v=>v.X)-50,y=pts.Min(v=>v.Y)-50,w=pts.Max(v=>v.X)-x+50,h=pts.Max(v=>v.Y)-y+50;string F(double n)=>n.ToString("0.####",CultureInfo.InvariantCulture);string line=string.Join(" ",pts.Select(v=>F(v.X)+","+F(v.Y)));File.WriteAllText(p,$"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"{F(x)} {F(y)} {F(w)} {F(h)}\"><polyline points=\"{line}\" fill=\"none\" stroke=\"#15263d\" stroke-width=\"{F(Project.Settings.RoadWidth)}\" stroke-linejoin=\"round\"/></svg>");}
    public void Generate(string style){var settings=Project.Copy().Settings;if(style=="rally"&&settings.Circuit&&!uiPreferences.AllowRallyCircuit){MessageBox.Show("Rally stages are point-to-point tracks. Uncheck Circuit in Geometry first, or enable the experimental rally circuit option in Preferences.","Invalid Configuration",MessageBoxButtons.OK,MessageBoxIcon.Error);return;}Project=Generators.Generate(style);settings.Circuit=style=="rally"?settings.Circuit:Project.Settings.Circuit;Project.Settings=settings;Ted=null;file=null;Canvas.Selected.Clear();Commit();Canvas.Fit();}
    public void Delete(){if(Ted!=null)return;foreach(int i in Canvas.Selected.OrderDescending())Project.Nodes.RemoveAt(i);Canvas.Selected.Clear();Commit();}
    void Duplicate(){if(Ted!=null)return;var copies=Canvas.Selected.Order().Select(i=>Project.Nodes[i].Copy()).ToList();foreach(var n in copies){n.X+=25;n.Y+=25;}int start=Project.Nodes.Count;Project.Nodes.AddRange(copies);Canvas.Selected=Enumerable.Range(start,copies.Count).ToHashSet();Commit();}
    void Insert(){if(Ted!=null||Project.Nodes.Count<2)return;int i=Canvas.Selected.Order().FirstOrDefault();int next=(i+1)%Project.Nodes.Count;var a=Project.Nodes[i];var b=Project.Nodes[next];Project.Nodes.Insert(i+1,new(){XY=(a.XY+b.XY)*.5,Z=(a.Z+b.Z)/2,Radius=(a.Radius+b.Radius)/2});Canvas.Selected=[i+1];Commit();}
    void Reverse(){if(Ted!=null)return;Project.Nodes.Reverse();Commit();}
    public void Transform(string action,double value){if(Ted!=null)return;var points=(Canvas.Selected.Count>0?Canvas.Selected.Select(i=>Project.Nodes[i]):Project.Nodes).ToList();if(points.Count==0)return;Vec center=new(points.Average(n=>n.X),points.Average(n=>n.Y));foreach(var n in points){Vec v=n.XY-center;if(action=="rotate"){double a=value*Math.PI/180;v=new(v.X*Math.Cos(a)-v.Y*Math.Sin(a),v.X*Math.Sin(a)+v.Y*Math.Cos(a));}if(action=="scale"){v*=value;n.Radius*=Math.Abs(value);}if(action=="mirrorX")v=new(-v.X,v.Y);if(action=="mirrorY")v=new(v.X,-v.Y);n.XY=center+v;}Commit();}
    void ScaleDialog(){double? value=NumberDialog("Scale selected nodes (or all nodes)","Factor",1,.001,1000);if(value.HasValue)Transform("scale",value.Value);}
    void Simplify(){if(Ted!=null)return;double? v=NumberDialog("Simplify path","Tolerance, metres",3,.01,1000);if(v.HasValue){Project.Nodes=Importers.Simplify(Project.Nodes,v.Value);Commit();}}
    void ImportPath(){using var d=new OpenFileDialog{Filter="Paths|*.csv;*.gpx;*.ted|All files|*.*"};if(d.ShowDialog()!=DialogResult.OK)return;if(!ConfirmDiscard())return;if(Path.GetExtension(d.FileName).Equals(".ted",StringComparison.OrdinalIgnoreCase)){var t=TedDocument.Read(File.ReadAllBytes(d.FileName));Project=Importers.FromTed(t);MessageBox.Show("The TED path has been sampled into editable nodes. Exporting this layout generates a new track. Open the TED normally to preserve its original geometry and tables.","Imported path");}else{Project=new(){Nodes=Path.GetExtension(d.FileName).Equals(".gpx",StringComparison.OrdinalIgnoreCase)?Importers.Gpx(d.FileName):Importers.Csv(d.FileName)};Project.Settings.Circuit=false;}Ted=null;file=null;Commit();Canvas.Fit();}
    void LoadReference(){using var d=new OpenFileDialog{Filter="Images|*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.tif;*.tiff"};if(d.ShowDialog()!=DialogResult.OK)return;using var image=new Bitmap(d.FileName);Canvas.Reference?.Dispose();Canvas.Reference=new Bitmap(image);Canvas.Invalidate();}
    void TraceImage(){using var d=new OpenFileDialog{Filter="Images|*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.tif;*.tiff"};if(d.ShowDialog()!=DialogResult.OK)return;double? width=NumberDialog("Trace a dark track on a light background","Target track size (m)",2000,10,50000);if(!width.HasValue)return;if(!ConfirmDiscard())return;using var image=new Bitmap(d.FileName);var path=ImageTracing.Trace(image,width.Value,imageTraceMode);if(path.Count<3)throw new InvalidDataException("No continuous dark track was found. Use a clean dark line on a light background.");bool closed=Geometry.Length(path[0].XY,path[^1].XY)<width.Value/10;if(closed&&Geometry.Length(path[0].XY,path[^1].XY)<.001)path.RemoveAt(path.Count-1);Project=new Project{Settings=Project.Copy().Settings,Nodes=path};Project.Settings.Circuit=closed;Ted=null;file=null;Canvas.Selected.Clear();Commit();Canvas.Fit();}
    public static double? NumberDialog(string title,string label,double value,double min,double max){using var f=new Form{Text=title,Width=430,Height=170,FormBorderStyle=FormBorderStyle.FixedDialog,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false};var l=new Label{Text=label,Left=15,Top=18,Width=220};var n=new NumericUpDown{Left=245,Top=15,Width=145,Minimum=(decimal)min,Maximum=(decimal)max,Value=(decimal)Math.Clamp(value,min,max),DecimalPlaces=3};var ok=new Button{Text="Apply",Left=300,Top=70,DialogResult=DialogResult.OK};f.Controls.AddRange([l,n,ok]);f.AcceptButton=ok;UiThemeDialogs.Apply(f);UiLanguage.Apply(f);return f.ShowDialog()==DialogResult.OK?(double)n.Value:null;}
}
